import { ActionDefinition } from '../../../Action'
import { ReferenceColumn, StringColumn } from '../../../../db'

export const getLatestResponseTextFromEmail = ActionDefinition({
    $id: 'a159d7820f13101051218e8ebc767eea',
    name: 'Get Latest Response Text From Email',
    description: 'This action provides the latest response text from body text of the email thread',
    inputs: {
        email_record: ReferenceColumn({
            label: 'Email Record',
            mandatory: true,
            referenceTable: 'sys_email',
        }),
    },
    outputs: {
        latest_response_text: StringColumn({
            label: 'Latest Response Text',
            mandatory: true,
            maxLength: 8000,
        }),
    },
})
